#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# _gh runs the GitHub CLI, finding it even when it is not on PATH. Git Bash on
# Windows often has a narrower PATH than the shell that installed gh, so a bare
# `command -v gh` reports "not installed" for a tool that is sitting right there.
# That exact miss silently skipped a secret write on 2026-08-24.
_gh() {
  if command -v gh >/dev/null 2>&1; then command gh "$@"; return; fi
  local c
  for c in "/c/Program Files/GitHub CLI/gh.exe"            "/c/Program Files (x86)/GitHub CLI/gh.exe"            "$LOCALAPPDATA/GitHubCLI/bin/gh.exe"; do
    [[ -x "$c" ]] && { "$c" "$@"; return; }
  done
  return 127
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if _gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | _gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if _gh auth status >/dev/null 2>&1; then
    if _gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Martha voice notes, the AWS side (.claude/skills/martha/VOICE-SETUP.md steps 2-6).
# Run in Git Bash on Windows, or a terminal on macOS or Linux, from anywhere:
#   bash alexa/setup/voice-setup.sh <the Martha Meals skill id>
# Safe to re-run: each stage checks or replaces what an earlier run made.
# ──────────────────────────────────────────────────────────────────────────

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
# A region set before running wins; otherwise stage 2 finds the one this account builds in.
REGION_GIVEN="${AWS_DEFAULT_REGION:-}"
export AWS_DEFAULT_REGION="${AWS_DEFAULT_REGION:-us-east-1}"
export AWS_PAGER=""
# Git Bash rewrites any argument that starts with "/" into a Windows path before a Windows
# program sees it: the key's name /martha-voice/anthropic-api-key reached AWS as
# "C:/Program Files/Git/martha-voice/..." and the save was refused (2026-11-17). Every file
# path here is converted on purpose with winpath, so the rewriting is switched off.
export MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*'
ENV_FILE="${MARTHA_VOICE_SETUP_ENV:-$HOME/.martha/voice-setup.env}"  # skill id and budget email only, never a secret
mkdir -p "$(dirname "$ENV_FILE")"
STACK=martha-voice
KEY_PARAMETER=/martha-voice/anthropic-api-key
PC_USER=martha-voice-pc
FUNCTION=martha-meal-skill

# Tools, found even when this shell's PATH is narrower than the one that installed them.
# `type -P` finds programs only: the wizard library above defines a shell function named `ask`.
_find() {
  local name="$1" c; shift
  if type -P "$name" >/dev/null 2>&1; then type -P "$name"; return 0; fi
  for c in "$@"; do [[ -x "$c" ]] && { printf '%s' "$c"; return 0; }; done
  return 1
}
AWS=$(_find aws "/c/Program Files/Amazon/AWSCLIV2/aws.exe" /usr/local/bin/aws) \
  || { warn "The AWS command-line tool isn't installed (VOICE-SETUP.md step 2)."; exit 1; }
ASK=$(_find ask "${APPDATA:-/none}/npm/ask" "$HOME/AppData/Roaming/npm/ask") \
  || { warn "The Alexa command-line tool isn't installed: npm install -g ask-cli, then ask configure (VOICE-SETUP.md step 1)."; exit 1; }
NODE=$(_find node "/c/Program Files/nodejs/node.exe") || { warn "Node.js isn't installed (VOICE-SETUP.md step 1)."; exit 1; }
NPM=$(_find npm "/c/Program Files/nodejs/npm") || { warn "npm isn't installed (VOICE-SETUP.md step 1)."; exit 1; }
PY=""
for c in python3 python py; do
  if command -v "$c" >/dev/null 2>&1 && "$c" --version >/dev/null 2>&1; then PY="$c"; break; fi
done
[[ -n "$PY" ]] || { warn "Python 3 isn't installed; Martha needs it."; exit 1; }

# A path that Windows programs (aws.exe, node.exe, python.exe) understand.
winpath() { if command -v cygpath >/dev/null 2>&1; then cygpath -w "$1"; else printf '%s' "$1"; fi; }

# The status of the skill's last update of one kind (manifest), from the Alexa tool.
skill_status() {
  "$ASK" smapi get-skill-status --skill-id "$SKILL_ID" --resource "$1" 2>/dev/null \
    | grep -o '"status": *"[A-Z_]*"' | head -n 1 | grep -o '[A-Z_]*"$' | tr -d '"'
}

TOTAL_STAGES=6
banner "Martha voice notes: the AWS side"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "An AWS account for the household"
say "Voice notes wait in a small table in your own AWS account. Expected cost: \$0 a month."
say "Already have the account? Press Enter."
open_url "https://portal.aws.amazon.com/billing/signup"
step "Sign up with an email you check; keep the password in your password manager."
step "Choose the Paid plan. The Free plan closes the account after 6 months."
step "Personal account, your card, the phone check, and the Basic (free) support plan."
pause "Press Enter once the account exists."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign this computer in to AWS"
say "A browser window opens for the AWS sign-in. It gives this computer a temporary sign-in,"
say "so no permanent admin key is saved here."
until "$AWS" login; do
  confirm "The sign-in didn't finish. Try again?" || { warn "Stopped. Run this again when you're ready."; exit 1; }
done
ACCOUNT=$("$AWS" sts get-caller-identity --query Account --output text)
say "Signed in to AWS account ${ACCOUNT}."
# Accounts from AWS's newer sign-up are "projects": they build (CloudFormation, Lambda,
# the notes table) in one region only, picked at sign-up from the contact address and
# fixed, and us-east-1 then serves account-wide services alone. On 2026-11-17 such an
# account's build was refused in us-east-1 and allowed in us-east-2. So unless a region
# was set, find the one CloudFormation answers in. An Alexa skill's back end may run in
# any Lambda region.
region_works() { "$AWS" cloudformation list-stacks --region "$1" --max-items 1 >/dev/null 2>&1; }
if [[ -z "$REGION_GIVEN" ]] && ! region_works "$AWS_DEFAULT_REGION"; then
  found=""
  for r in us-east-2 us-west-2 us-west-1 ca-central-1 eu-west-1 eu-west-2 eu-central-1 \
           ap-southeast-2 ap-northeast-1 ap-south-1 sa-east-1; do
    if region_works "$r"; then found="$r"; break; fi
  done
  [[ -n "$found" ]] || { warn "AWS refused building in every region tried. Sign in again (run this again), and if"
                         warn "it still fails, run it with your account's region set: AWS_DEFAULT_REGION=<region> bash ..."; exit 1; }
  export AWS_DEFAULT_REGION="$found"
fi
say "Building in region ${AWS_DEFAULT_REGION}."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Build the voice-notes pieces in AWS"
say "The notes table, the skill's back end, a narrow key user for this computer,"
say "and a \$1 monthly budget alert."
SKILL_ID="${1:-}"
[[ -n "$SKILL_ID" ]] || ask SKILL_ID "The Martha Meals skill id (amzn1.ask.skill...):"
[[ "$SKILL_ID" =~ ^amzn1\.ask\.skill\.[0-9a-f-]+$ ]] || { warn "That isn't a skill id (VOICE-SETUP.md step 1)."; exit 1; }
write_env SKILL_ID "$SKILL_ID"
ask BUDGET_EMAIL "Email for the budget alert (AWS writes only if a month costs over \$1):"
[[ "$BUDGET_EMAIL" == *@*.* ]] || { warn "That isn't an email address."; exit 1; }
write_env BUDGET_EMAIL "$BUDGET_EMAIL"
note "Building. This takes one to three minutes."
if ! "$AWS" cloudformation deploy --stack-name "$STACK" \
     --template-file "$(winpath "$ROOT/alexa/infra/martha-voice.yaml")" \
     --capabilities CAPABILITY_NAMED_IAM --no-fail-on-empty-changeset \
     --parameter-overrides "AlexaSkillId=$SKILL_ID" "BudgetEmail=$BUDGET_EMAIL"; then
  warn "AWS couldn't build it. What it said:"
  "$AWS" cloudformation describe-stack-events --stack-name "$STACK" --output text \
    --query "StackEvents[?contains(ResourceStatus,'FAILED')].[LogicalResourceId,ResourceStatusReason]" | head -n 8
  exit 1
fi
FUNCTION_ARN=$("$AWS" cloudformation describe-stacks --stack-name "$STACK" --output text \
  --query "Stacks[0].Outputs[?OutputKey=='FunctionArn'].OutputValue")
say "Built."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The Anthropic API key for Alexa's read-back"
say "Alexa repeats back what she understood using Claude Haiku. That needs an Anthropic API key,"
say "billed apart from any Claude plan: about 15 cents a month at ten notes a day."
open_url "https://console.anthropic.com/settings/keys"
step "Billing: add a small prepaid amount (\$5 lasts a long time here) and leave auto-reload off."
step "API keys: Create key, name it martha-meal, and copy it."
ANTHROPIC_KEY=""
ask_secret ANTHROPIC_KEY "Paste the key (hidden). Press Enter alone to keep a key saved earlier:"
if [[ -n "$ANTHROPIC_KEY" ]]; then
  [[ "$ANTHROPIC_KEY" == sk-ant-* ]] || warn "That doesn't start with sk-ant-; saving it anyway."
  keyfile=$(mktemp); chmod 600 "$keyfile"; printf '%s' "$ANTHROPIC_KEY" > "$keyfile"; ANTHROPIC_KEY=""
  if "$AWS" ssm put-parameter --name "$KEY_PARAMETER" --type SecureString --overwrite \
       --value "file://$(winpath "$keyfile")" >/dev/null; then
    rm -f -- "$keyfile"; say "Saved, encrypted, where only the skill's back end can read it."
  else
    rm -f -- "$keyfile"; warn "AWS didn't save the key. Run this again."; exit 1
  fi
elif "$AWS" ssm get-parameter --name "$KEY_PARAMETER" --query Parameter.Name --output text >/dev/null 2>&1; then
  say "Keeping the key saved earlier."
else
  warn "No key saved yet. Alexa will save notes as said, without the read-back, until you re-run this."
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Give this computer its own narrow key"
say "Martha reads and deletes notes with a key that can't reach anything else in the account."
say "It goes straight from AWS into Martha's credentials file; it is never shown."
keys=$("$AWS" iam list-access-keys --user-name "$PC_USER" --query 'length(AccessKeyMetadata)' --output text)
if [[ "$keys" -ge 2 ]]; then
  warn "This computer's user already has two keys, the most AWS allows. In the AWS console, open"
  warn "IAM > Users > $PC_USER > Security credentials, delete the older key, then run this again."
  exit 1
fi
read -r MARTHA_VOICE_KEY_ID MARTHA_VOICE_SECRET < <("$AWS" iam create-access-key --user-name "$PC_USER" \
  --query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text)
[[ -n "${MARTHA_VOICE_SECRET:-}" ]] || { warn "AWS didn't make the key. Run this again."; exit 1; }
# The region goes with the key: without it Martha would look for the notes in us-east-1.
MARTHA_VOICE_REGION="$AWS_DEFAULT_REGION"
export MARTHA_VOICE_KEY_ID MARTHA_VOICE_SECRET MARTHA_VOICE_REGION
note "Waiting 15 seconds for AWS to switch the new key on..."
sleep 15
if "$PY" "$(winpath "$ROOT/.claude/skills/martha/scripts/martha_voice.py")" setup --from-env; then
  say "This computer can read Martha's notes."
else
  warn "The key is saved but the check failed; the message above says why (VOICE-SETUP.md step 6)."
fi
unset MARTHA_VOICE_KEY_ID MARTHA_VOICE_SECRET
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Upload the skill's code and connect it to Alexa"
build=$(mktemp -d)
cp -r "$ROOT/alexa/lambda/index.js" "$ROOT/alexa/lambda/lib" "$ROOT/alexa/lambda/package.json" \
      "$ROOT/alexa/lambda/package-lock.json" "$build/"
note "Packing the code..."
(cd "$build" && "$NPM" ci --omit=dev --no-audit --no-fund >/dev/null)
if command -v zip >/dev/null 2>&1; then
  (cd "$build" && zip -qr function.zip index.js lib node_modules package.json)
else
  w=$(winpath "$build")
  powershell.exe -NoProfile -Command "Compress-Archive -Path '$w\\index.js','$w\\lib','$w\\node_modules','$w\\package.json' -DestinationPath '$w\\function.zip' -Force"
fi
"$AWS" lambda update-function-code --function-name "$FUNCTION" \
  --zip-file "fileb://$(winpath "$build/function.zip")" --query LastUpdateStatus --output text >/dev/null
"$AWS" lambda wait function-updated-v2 --function-name "$FUNCTION"
rm -rf -- "$build"
say "Code uploaded."
FUNCTION_ARN=${FUNCTION_ARN:-$("$AWS" lambda get-function --function-name "$FUNCTION" --query Configuration.FunctionArn --output text)}
manifest=$(mktemp)
"$NODE" -e "const fs=require('fs');const m=JSON.parse(fs.readFileSync(process.argv[1],'utf8'));m.manifest.apis.custom.endpoint={uri:process.argv[2]};fs.writeFileSync(process.argv[3],JSON.stringify(m));" \
  "$(winpath "$ROOT/alexa/skill-package/skill.json")" "$FUNCTION_ARN" "$(winpath "$manifest")"
"$ASK" smapi update-skill-manifest --skill-id "$SKILL_ID" --stage development --manifest "file:$(winpath "$manifest")" >/dev/null 2>&1
rm -f -- "$manifest"
s=""
for _ in $(seq 1 30); do
  s=$(skill_status manifest); [[ "$s" == "IN_PROGRESS" ]] || break; sleep 3
done
[[ "$s" == "SUCCEEDED" ]] || { warn "Alexa didn't accept the connection (status: ${s:-unknown}). Run this again."; exit 1; }
"$ASK" smapi set-skill-enablement --skill-id "$SKILL_ID" --stage development >/dev/null 2>&1 || true
say "Connected. Alexa now sends Martha Meals' notes to your AWS account."
pause

finish
say "Try it: \"Alexa, ask Martha Meals to note that we're out of ground cumin.\""
say "Then, from the Martha folder: python .claude/skills/martha/scripts/martha_voice.py notes"
say "Last step: turn voice notes on for Martha (VOICE-SETUP.md step 7)."
printf '\n'

